// Procedural bronchial tree (generated by tools/build_models.mjs from BodyParts3D
// segmental anatomy) rendered as tapered tubes, plus tidal airflow particles.
import * as THREE from 'three';
import { U, patchMaterial, BREATHE_GLSL, TISSUE_OUTPUT, breatheLungJS } from './breathing.js';

export class Airways {
  constructor() {
    this.group = new THREE.Group();
    this.narrow = { value: 0 };
    this.routeGlow = { value: 0 };
    this.nearFade = { value: new THREE.Vector2(0, 0) };
    this.keepGen = { value: -10 }; // airway flight: hide sub-trees that left the route before this generation
    this.inflame = { value: 0 };
    this.highlight = { value: 0 };
  }

  async load() {
    const data = await (await fetch('assets/data/airways.json')).json();
    this.data = data;
    const N = data.nodes.length;
    this.pos = new Float32Array(N * 3);
    this.rad = new Float32Array(N);
    this.parent = new Int32Array(N);
    this.gen = new Uint8Array(N);
    this.children = Array.from({ length: N }, () => []);
    data.nodes.forEach((n, i) => {
      this.pos[3 * i] = n[0]; this.pos[3 * i + 1] = n[1]; this.pos[3 * i + 2] = n[2];
      this.rad[i] = n[3]; this.parent[i] = n[4]; this.gen[i] = n[5];
      if (n[4] >= 0) this.children[n[4]].push(i);
    });
    this.maxGen = Math.max(...this.gen);
    this.buildPaths();
    this.route = this.flightPath();
    this.onRoute = new Set(this.route.chain);
    // generation at which each branch diverges from the flight route
    this.div = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      const p = this.parent[i];
      this.div[i] = this.onRoute.has(i) || p < 0 ? 99 : this.onRoute.has(p) ? this.gen[p] : this.div[p];
    }
    this.buildMesh();
    this.buildParticles();
    return this;
  }

  P(i, v = new THREE.Vector3()) { return v.set(this.pos[3 * i], this.pos[3 * i + 1], this.pos[3 * i + 2]); }

  buildMesh() {
    const N = this.parent.length;
    const positions = [], normals = [], centers = [], gens = [], indices = [], route = [], divs = [];
    const a = new THREE.Vector3(), b = new THREE.Vector3(), d = new THREE.Vector3();
    const u = new THREE.Vector3(), w = new THREE.Vector3(), tmp = new THREE.Vector3();
    let vbase = 0;
    const addTube = (i) => {
      const p = this.parent[i];
      this.P(p, a); this.P(i, b);
      d.subVectors(b, a); const L = d.length(); if (L < 1e-5) return; d.divideScalar(L);
      tmp.set(Math.abs(d.y) < 0.9 ? 0 : 1, Math.abs(d.y) < 0.9 ? 1 : 0, 0);
      u.crossVectors(d, tmp).normalize(); w.crossVectors(d, u);
      const g = this.gen[i];
      const onR = this.onRoute.has(i) ? 1 : 0;
      const seg = g < 4 ? 20 : g < 8 ? 14 : 12;
      const r1 = this.rad[i], r0 = Math.min(this.rad[p], r1 * 1.25);
      // start slightly inside the parent so joints are closed
      const a0 = a.clone().addScaledVector(d, -Math.min(r0 * 0.5, L * 0.3));
      for (let ring = 0; ring < 2; ring++) {
        const c = ring === 0 ? a0 : b, r = ring === 0 ? r0 : r1;
        for (let s = 0; s < seg; s++) {
          const t = s / seg * Math.PI * 2;
          const nx = u.x * Math.cos(t) + w.x * Math.sin(t), ny = u.y * Math.cos(t) + w.y * Math.sin(t), nz = u.z * Math.cos(t) + w.z * Math.sin(t);
          positions.push(c.x + nx * r, c.y + ny * r, c.z + nz * r);
          normals.push(nx, ny, nz);
          centers.push(c.x, c.y, c.z);
          gens.push(g);
          route.push(onR); divs.push(this.div[i]);
        }
      }
      for (let s = 0; s < seg; s++) {
        const s1 = (s + 1) % seg;
        indices.push(vbase + s, vbase + s1, vbase + seg + s, vbase + s1, vbase + seg + s1, vbase + seg + s);
      }
      vbase += seg * 2;
    };
    const addCap = (i) => { // rounded joint / tip
      const g = this.gen[i], r = this.rad[i];
      const c = this.P(i, new THREE.Vector3());
      const sg = g < 6 ? capHi : capLo; // smooth, indexed unit spheres
      const pp = sg.attributes.position, nn = sg.attributes.normal, ix = sg.index;
      for (let k = 0; k < pp.count; k++) {
        positions.push(c.x + pp.getX(k) * r, c.y + pp.getY(k) * r, c.z + pp.getZ(k) * r);
        normals.push(nn.getX(k), nn.getY(k), nn.getZ(k));
        centers.push(c.x, c.y, c.z); gens.push(g); route.push(this.onRoute.has(i) ? 1 : 0); divs.push(this.div[i]);
      }
      for (let k = 0; k < ix.count; k++) indices.push(vbase + ix.getX(k));
      vbase += pp.count;
    };
    const capHi = new THREE.SphereGeometry(1, 18, 12), capLo = new THREE.SphereGeometry(1, 12, 8);
    for (let i = 0; i < N; i++) {
      if (this.parent[i] < 0) continue;
      if (this.gen[i] < 2) continue; // trachea and main bronchi are the real BodyParts3D meshes
      addTube(i);
      if (this.gen[i] < 9 || this.children[i].length === 0) addCap(i);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    geo.setAttribute('aCenter', new THREE.Float32BufferAttribute(centers, 3));
    geo.setAttribute('aGen', new THREE.Float32BufferAttribute(gens, 1));
    geo.setAttribute('aRoute', new THREE.Float32BufferAttribute(route, 1));
    geo.setAttribute('aDiv', new THREE.Float32BufferAttribute(divs, 1));
    geo.setIndex(indices);
    geo.computeBoundingSphere();

    const mat = new THREE.MeshPhysicalMaterial({
      color: 0xd9a39c, roughness: 0.5, sheen: 0.6, sheenColor: new THREE.Color(0xffc2bb), clearcoat: 0.35, clearcoatRoughness: 0.35, envMapIntensity: 0.7,
    });
    patchMaterial(mat, {
      kind: 'lung', key: 'tree',
      extra: {
        uNarrow: this.narrow, uInflame: this.inflame, uTar: { value: 0 }, uSSS: { value: new THREE.Color(0xff6b6b) },
        uSSSStrength: { value: 0.22 }, uRouteGlow: this.routeGlow, uKeepGen: this.keepGen, uXray: { value: 0 }, uFade: { value: 1 },
      },
      vertexPre: 'attribute vec3 aCenter; attribute float aGen; attribute float aRoute; attribute float aDiv; varying float vGen; varying float vRoute; varying float vDiv; uniform float uNarrow;',
      preDeform: /* glsl */`
        vGen = aGen; vRoute = aRoute; vDiv = aDiv;
        // bronchoconstriction: smooth muscle narrows small bronchi and bronchioles most
        float nf = uNarrow * 0.5 * smoothstep(3.5, 7.0, aGen);
        transformed = aCenter + (transformed - aCenter) * (1.0 - nf);
      `,
      fragment: {
        color: /* glsl */`
          // airway flight: sub-trees that left the route earlier dissolve away
          {
            float keep = smoothstep(uKeepGen - 1.0, uKeepGen, vDiv);
            if (keep < 0.999) {
              float h = fract(sin(dot(floor(gl_FragCoord.xy), vec2(12.9898, 78.233))) * 43758.5453);
              if (h > keep) discard;
            }
          }
          diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.82, 0.98, 1.12), uRouteGlow * vRoute);
          diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.86, 0.32, 0.34), uInflame * 0.55 * smoothstep(3.0, 7.0, vGen));
          diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.6, 0.55, 0.5), uTar * 0.5);
        `,
        output: TISSUE_OUTPUT,
      },
    });
    // the vGen varying must also exist in the fragment shader
    const prev = mat.onBeforeCompile;
    mat.onBeforeCompile = (sh) => { prev(sh); sh.fragmentShader = sh.fragmentShader.replace('varying vec3 vObjPos;', 'varying vec3 vObjPos;\nvarying float vGen;\nvarying float vRoute;\nvarying float vDiv;'); };
    this.material = mat;
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.userData.partId = 'bronchial_tree';
    this.mesh.renderOrder = 1;
    this.group.add(this.mesh);
  }

  buildPaths() {
    const N = this.parent.length;
    const leaves = [];
    for (let i = 0; i < N; i++) if (this.children[i].length === 0) leaves.push(i);
    this.leaves = leaves;
    // root-to-leaf polylines with cumulative arc length
    const top = this.P(0, new THREE.Vector3());
    this.paths = leaves.map(leaf => {
      const chain = [];
      for (let i = leaf; i >= 0; i = this.parent[i]) chain.push(i);
      chain.reverse();
      const pts = [top.clone().add(new THREE.Vector3(0, 0.07, 0.012)), ...chain.map(i => this.P(i, new THREE.Vector3()))];
      const cum = [0];
      for (let k = 1; k < pts.length; k++) cum.push(cum[k - 1] + pts[k].distanceTo(pts[k - 1]));
      return { pts, cum, chain, len: cum[cum.length - 1], leaf, lead: pts[1].distanceTo(pts[0]) };
    });
  }

  // point along a path at arc length s
  pathPoint(path, s, out) {
    const { pts, cum } = path;
    if (s <= 0) return out.copy(pts[0]);
    if (s >= path.len) return out.copy(pts[pts.length - 1]);
    let lo = 0, hi = cum.length - 1;
    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (cum[m] < s) lo = m; else hi = m; }
    const t = (s - cum[lo]) / (cum[hi] - cum[lo] || 1);
    return out.copy(pts[lo]).lerp(pts[hi], t);
  }

  buildParticles() {
    const COUNT = 2600;
    this.count = COUNT;
    const geo = new THREE.BufferGeometry();
    this.pPos = new Float32Array(COUNT * 3);
    this.pCol = new Float32Array(COUNT * 3);
    this.pAlpha = new Float32Array(COUNT);
    this.pSize = new Float32Array(COUNT);
    geo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('color', new THREE.BufferAttribute(this.pCol, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.pAlpha, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('size', new THREE.BufferAttribute(this.pSize, 1));
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1);
    this.particles = [];
    for (let i = 0; i < COUNT; i++) {
      this.particles.push(this.newParticle({}));
      this.pSize[i] = 0.6 + Math.random() * 0.8;
    }
    const mat = new THREE.ShaderMaterial({
      uniforms: { ...U, uScale: { value: 1 }, uPx: { value: 1 } },
      vertexShader: /* glsl */`
        ${BREATHE_GLSL}
        attribute float alpha; attribute float size; attribute vec3 color;
        varying float vA; varying vec3 vC;
        uniform float uScale; uniform float uPx;
        void main() {
          vec3 p = breatheLung(position);
          vec4 mv = modelViewMatrix * vec4(p, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = size * uScale * uPx / -mv.z;
          gl_PointSize = clamp(gl_PointSize, 0.0, 26.0 * uPx);
          vA = alpha; vC = color;
        }`,
      fragmentShader: /* glsl */`
        varying float vA; varying vec3 vC;
        void main() {
          vec2 c = gl_PointCoord - 0.5; float d = dot(c, c);
          if (d > 0.25) discard;
          float a = exp(-d * 14.0) * vA;
          gl_FragColor = vec4(vC * a, a);
        }`,
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    });
    this.pMat = mat;
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 30;
    this.group.add(this.points);
    this.fresh = new THREE.Color(0x9fe8ff);
    this.stale = new THREE.Color(0x8f86ff);
    this.smoke = new THREE.Color(0x8a8178);
  }

  newParticle(p) {
    // during the airway flight a share of the air follows the branch being explored
    p.path = Math.random() < (this.routeShare || 0) && this.route ? this.route : this.paths[(Math.random() * this.paths.length) | 0];
    // offset < 0: still outside (in the mouth/nose), > 0: already in the airways (dead space air)
    p.o = -1.15 + Math.random() * 1.45;
    p.jit = Math.random();
    p.deep = 0;
    p.smoke = Math.random();
    return p;
  }

  // q: fraction of the airway path reached; velocity falls distally as total cross-section grows
  update(dt, phys, opts) {
    const v = phys.v;
    this.narrow.value += ((phys.p.narrowing) - this.narrow.value) * (1 - Math.exp(-dt / 0.8));
    this.inflame.value = this.narrow.value;
    this.material.userData.uniforms.uTar.value = phys.p.tar;
    const reach = 0.9 * Math.min(1.6, Math.pow(phys.vt / 500, 0.55)) * (1 - 0.3 * this.narrow.value);
    const density = phys.p.pb / 760; // fewer molecules per breath at altitude
    const smokeShare = phys.p.tar * 0.18;
    const tmp = new THREE.Vector3(), tcol = new THREE.Color();
    // arc position of the camera focus on the route (airway view only)
    let sFocus = -1, s0 = 0, s1 = 0;
    if (this.routeShare && opts.focus) {
      const r = this.route; let best = 1e9;
      for (let k = 0; k < r.pts.length; k++) { const d = r.pts[k].distanceToSquared(opts.focus); if (d < best) { best = d; sFocus = r.cum[k]; } }
      s0 = Math.max(0, sFocus - 0.008); s1 = r.len;
    }
    const newCycle = phys.phase < this._lastPhase;
    this._lastPhase = phys.phase;
    for (let i = 0; i < this.count; i++) {
      const p = this.particles[i];
      if (newCycle) {
        if (p.o + 0 < 0 || p.o > 0.35 || Math.random() < 0.5) this.newParticle(p);
      }
      if (sFocus >= 0 && p.path === this.route) {
        // airway view: local tidal stream through the explored bronchus, around the camera
        const f = ((p.jit * 7.31 + v * 1.6 * reach) % 1 + 1) % 1;
        const sp = s0 + (s1 - s0) * f;
        this.pathPoint(this.route, sp, tmp);
        const jr = 0.00045 * (p.smoke - 0.5), jr2 = 0.00045 * (p.jit * 3.7 % 1 - 0.5);
        this.pPos[3 * i] = tmp.x + jr; this.pPos[3 * i + 1] = tmp.y + jr2; this.pPos[3 * i + 2] = tmp.z - jr;
        const c = phys.inhaling ? this.fresh : tcol.copy(this.fresh).lerp(this.stale, 0.8);
        this.pCol[3 * i] = c.r; this.pCol[3 * i + 1] = c.g; this.pCol[3 * i + 2] = c.b;
        this.pAlpha[i] = Math.sin(Math.PI * f) * opts.visibility * (p.jit > density ? 0.15 : 1);
        continue;
      }
      const q = p.o + v * reach;
      if (q > p.deep) p.deep = q;
      const qq = Math.min(1, Math.max(0, q));
      const s = p.path.lead + (p.path.len - p.path.lead) * (1 - Math.pow(1 - qq, 1.7));
      let sPos = q < 0 ? p.path.lead * (1 + q * 0.9) : s;
      this.pathPoint(p.path, sPos, tmp);
      // tiny lateral jitter so particles fill the lumen
      const jr = 0.0035 * (1 - qq) * (p.jit - 0.5);
      this.pPos[3 * i] = tmp.x + jr; this.pPos[3 * i + 1] = tmp.y + jr * 0.6; this.pPos[3 * i + 2] = tmp.z - jr;
      let alpha = q < -0.95 ? 0 : q < 0 ? (q + 0.95) / 0.95 : q > 0.97 ? Math.max(0, 1 - (q - 0.97) / 0.06) : 1;
      if (p.jit > density) alpha *= 0.12;
      const staleMix = Math.min(1, Math.max(0, (p.deep - 0.55) / 0.35)) * (phys.inhaling ? 0.5 : 1);
      const isSmoke = p.smoke < smokeShare;
      const c = isSmoke ? this.smoke : tcol.copy(this.fresh).lerp(this.stale, staleMix);
      this.pCol[3 * i] = c.r; this.pCol[3 * i + 1] = c.g; this.pCol[3 * i + 2] = c.b;
      const onRouteP = !this.routeShare || p.path === this.route;
      this.pAlpha[i] = onRouteP ? alpha * opts.visibility * (isSmoke ? 0.8 : 1) : 0;
    }
    const g = this.points.geometry;
    g.attributes.position.needsUpdate = true;
    g.attributes.color.needsUpdate = true;
    g.attributes.alpha.needsUpdate = true;
    this.pMat.uniforms.uScale.value = opts.pointScale;
    this.pMat.depthTest = !this.routeShare; // airway view: air glows through the bronchial wall
    this.pMat.uniforms.uPx.value = opts.pixelRatio;
    this.material.userData.uniforms.uFade.value = 1;
  }

  // a long path into the right lower lobe (posterior basal) for the airway flight
  flightPath() {
    const segIdx = this.data.segments.findIndex(s => /Right posterior basal/i.test(s.name));
    let best = null;
    for (const path of this.paths) {
      const seg = this.data.nodes[path.leaf][6];
      if (seg !== segIdx) continue;
      const score = path.chain.length * 10 - Math.abs(path.len - 0.24) * 200;
      if (!best || score > best.score) best = { path, score };
    }
    return (best || { path: this.paths[0] }).path;
  }

  genAtFace(faceIndex) {
    const g = this.mesh.geometry;
    const vi = g.index.getX(faceIndex * 3);
    return g.attributes.aGen.getX(vi);
  }

  deformed(i, out = new THREE.Vector3()) { return breatheLungJS(this.P(i, out), out); }
}
